import 'dart:io';

import 'package:flutter_test/flutter_test.dart';

import 'package:meshmore_sns_app/legal/shipped_packages.dart';

/// The licence page is a legal obligation, not a screen.
///
/// `kShippedPackages` is generated by `tools/gen_credits_list.dart`, which is
/// run by hand, and nothing checked it. A dependency added to `pubspec.yaml`
/// and not regenerated is a licence the app ships without listing — and the
/// page that exists to satisfy that obligation would look complete.
///
/// This gate reads the direct dependencies out of `pubspec.yaml` and asserts
/// each one is named. It cannot see a transitive package, which is what the
/// generator is for; it can see the one case a hurried edit produces.
void main() {
  test('every direct dependency is named on the licence page', () {
    final List<String> lines = File('pubspec.yaml').readAsLinesSync();
    final List<String> direct = <String>[];
    bool inDeps = false;
    for (final String line in lines) {
      if (line.startsWith('dependencies:')) {
        inDeps = true;
        continue;
      }
      if (inDeps && line.isNotEmpty && !line.startsWith(' ')) {
        inDeps = false;
      }
      if (!inDeps) continue;
      final RegExpMatch? m = RegExp(r'^  ([a-z0-9_]+):').firstMatch(line);
      if (m != null) direct.add(m.group(1)!);
    }
    expect(direct, isNotEmpty, reason: 'the pubspec parse found no dependencies');
    final Set<String> shipped = kShippedPackages.toSet();
    final List<String> missing = <String>[
      for (final String name in direct)
        if (!shipped.contains(name)) name,
    ];
    expect(missing, isEmpty,
        reason: 'these direct dependencies are not on the licence page, so the '
            'app ships their licence without listing it: $missing. Run '
            '`dart run tools/gen_credits_list.dart`.');
  });

  test('the list is alphabetical and has no duplicates', () {
    final List<String> sorted = List<String>.of(kShippedPackages)..sort();
    expect(kShippedPackages, sorted,
        reason: 'the generator sorts the list; a hand edit must keep it sorted');
    expect(kShippedPackages.toSet().length, kShippedPackages.length,
        reason: 'a package named twice is a row drawn twice');
  });
}
